#!/usr/bin/env node
'use strict';
const {chromium}=require('playwright');
const assert=require('node:assert/strict');
const fs=require('node:fs');
const out='/tmp/v8-rosny';fs.mkdirSync(out,{recursive:true});
(async()=>{
 const browser=await chromium.launch({headless:true});
 try{for(const width of [320,390,768,1440]){
  const page=await browser.newPage({viewport:{width,height:900},deviceScaleFactor:1});
  const errors=[], failed=[];
  page.on('pageerror',e=>errors.push(e.message));
  page.on('response',res=>{if(res.status()>=400 && /rosny-bod|rv-brand|logo-rv/.test(res.url()))failed.push(`${res.status()} ${res.url()}`)});
  const response=await page.goto('http://127.0.0.1:8765/rosny-bod-kalkulacka.html',{waitUntil:'networkidle'});
  assert.equal(response.status(),200);
  assert.equal(await page.locator('h1').count(),1);
  assert.equal(await page.locator('link[rel=canonical]').getAttribute('href'),'https://rychlevypocty.cz/rosny-bod-kalkulacka.html');
  assert.ok((await page.locator('meta[name=description]').getAttribute('content')).length>80);
  assert.ok(await page.locator('script[type="application/ld+json"]').count()>=2);
  assert.equal(await page.locator('img').evaluateAll(els=>els.every(el=>el.complete&&el.naturalWidth>0)),true,'Both authentic logos render');
  assert.deepEqual(failed,[],`Missing product asset ${width}`);
  assert.deepEqual(errors,[],`Initial runtime error ${width}`);
  assert.match(await page.locator('#resultHeadline').innerText(),/13,9|14,0/);
  assert.match(await page.locator('#quickDew').innerText(),/13,9|14,0/);
  const ids=await page.locator('[id]').evaluateAll(nodes=>nodes.map(e=>e.id));
  assert.equal(new Set(ids).size,ids.length,'No duplicate DOM IDs');
  const checkLayout=async()=>assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),true,`Horizontal overflow ${width}`);
  await checkLayout();
  await page.screenshot({path:`${out}/rosny-${width}-initial.png`});
  await page.screenshot({path:`${out}/rosny-${width}-full.png`,fullPage:true});
  await page.locator('#air').fill('');
  assert.match(await page.locator('#resultHeadline').innerText(),/Zkontrolujte/);
  for(const id of ['quickDew','kpiDew','scenario40'])assert.equal(await page.locator('#'+id).innerText(),'—',`Stale ${id}`);
  await page.locator('#air').fill('22');
  await page.locator('#rh').fill('101');
  assert.match(await page.locator('#resultHeadline').innerText(),/Zkontrolujte/);
  await page.locator('#rh').fill('60');
  assert.match(await page.locator('#resultHeadline').innerText(),/13,9|14,0/);
  await page.locator('[data-mode=surface]').click();
  assert.equal(await page.locator('#surfaceField').isVisible(),true);
  assert.match(await page.locator('#kpiMargin').innerText(),/\+3,/);
  assert.equal(await page.locator('#thresholdWrap').isVisible(),true);
  assert.match(await page.locator('#thresholdValue').innerText(),/% RH/);
  await page.locator('#surface').fill('10');
  assert.match(await page.locator('#meaningTitle').innerText(),/kondenzace/);
  assert.equal(await page.locator('#glassPane').evaluate(e=>e.classList.contains('is-wet')),true);
  await page.locator('#surface').fill('');
  assert.equal(await page.locator('#kpiMargin').innerText(),'—');
  await page.locator('#surface').fill('17');
  await page.locator('[data-rh-preset="40"]').click();
  assert.equal(await page.locator('#rh').inputValue(),'40');
  assert.match(await page.locator('#scenarioCurrent').innerText(),/40/);
  await page.locator('#resetBtn').click();
  assert.equal(await page.locator('#surfaceField').isVisible(),false);
  assert.equal(await page.locator('#rh').inputValue(),'60');
  const physics=await page.evaluate(()=>window.RVDewPointCore.calculate({airTempC:22,rhPct:60}));
  assert.equal(physics.ok,true);assert.ok(physics.dewPointC>13.5&&physics.dewPointC<14.5);
  await checkLayout();
  assert.deepEqual(errors,[],`Scenario runtime error ${width}`);
  assert.deepEqual(failed,[],`Resource failures ${width}`);
  console.log('PASS',width,'real product, SEO, logos, inputs, invalidation/recovery, surface/threshold/glass, scenarios, reset, physics, overflow, no JS errors');
  await page.close();
 }}finally{await browser.close();}
})().catch(e=>{console.error(e);process.exitCode=1});
